import {AppError, savedFilterInput, validatedQuery, integer, normalizeSearch} from '@crew/shared';
import {searchAccess, validateQueryProjects} from './search.js';

export function publicFilter(row, userId) {
  return {id: row.id, orgId: row.org_id, ownerId: row.owner_id, teamId: row.team_id,
    visibility: row.visibility, name: row.name, description: row.description, query: row.query,
    revision: row.revision, createdAt: row.created_at, updatedAt: row.updated_at, canEdit: row.owner_id === userId};
}

function teamMember(ctx, userId, teamId, orgId) {
  return Boolean(ctx.db.prepare(`SELECT 1 FROM teams t JOIN team_members tm ON tm.team_id=t.id
    WHERE t.id=? AND t.org_id=? AND tm.user_id=?`).get(teamId, orgId, userId));
}

function queryVisible(ctx, row, projectIds) {
  try {
    validateQueryProjects(ctx, validatedQuery(row.query).ast, row.org_id, projectIds);
    return true;
  } catch (error) {
    if (error.code === 'FORBIDDEN') return false;
    throw error;
  }
}

export function canReadFilter(ctx, req, row) {
  if (!ctx.permissions.membership(req.user.id, row.org_id)) return false;
  if (row.visibility === 'personal' && row.owner_id !== req.user.id) return false;
  if (row.visibility === 'team' && !teamMember(ctx, req.user.id, row.team_id, row.org_id)) return false;
  const projectIds = ctx.permissions.projectIds(req.user.id, row.org_id).filter(id => ctx.permissions.canProject(req.user.id, id, 'insight:read'));
  return queryVisible(ctx, row, projectIds);
}

export function getFilter(ctx, req, id, {edit = false} = {}) {
  ctx.permissions.scope(req, edit ? 'insight:write' : 'insight:read');
  const row = ctx.db.prepare('SELECT * FROM saved_filters WHERE id=?').get(id);
  if (!row || !canReadFilter(ctx, req, row)) throw new AppError('NOT_FOUND', 'Saved filter not found', 404);
  if (edit) {
    if (row.owner_id !== req.user.id) throw new AppError('FORBIDDEN', 'Only the filter creator can change it', 403);
    ctx.permissions.assertOrg(req, row.org_id, 'insight:write');
  }
  return publicFilter(row, req.user.id);
}

export function listFilters(ctx, req) {
  const access = searchAccess(ctx, req);
  if (req.query.visibility && !['personal', 'team', 'all'].includes(req.query.visibility)) throw new AppError('VALIDATION', 'Unknown filter visibility', 422, {visibility: 'Choose personal, team or all'});
  const nameQuery = normalizeSearch(req.query.q ?? '').trim();
  if (nameQuery.length > 100) throw new AppError('VALIDATION', 'Filter lookup is too long', 422, {q: 'Use at most 100 characters'});
  if (req.query.owned && !['true', 'false'].includes(req.query.owned)) throw new AppError('VALIDATION', 'Invalid ownership filter', 422, {owned: 'Choose true or false'});
  const rows = ctx.db.prepare('SELECT * FROM saved_filters WHERE org_id=? ORDER BY updated_at DESC,id').all(access.orgId);
  const items = rows.filter(row => canReadFilter(ctx, req, row))
    .filter(row => !nameQuery || normalizeSearch(row.name + ' ' + row.description).includes(nameQuery))
    .filter(row => !req.query.visibility || req.query.visibility === 'all' || row.visibility === req.query.visibility)
    .filter(row => !req.query.teamId || row.team_id === req.query.teamId)
    .filter(row => req.query.owned !== 'true' || row.owner_id === req.user.id)
    .map(row => publicFilter(row, req.user.id));
  return {...ctx.paginate(items, req.query), total: items.length};
}

function checkFilter(ctx, req, input) {
  ctx.permissions.assertOrg(req, input.orgId, 'insight:write');
  const projects = ctx.permissions.projectIds(req.user.id, input.orgId);
  validateQueryProjects(ctx, validatedQuery(input.query).ast, input.orgId, projects);
  if (input.visibility === 'team') {
    if (!input.teamId || !teamMember(ctx, req.user.id, input.teamId, input.orgId)) throw new AppError('VALIDATION', 'Choose one of your teams in this organization', 422, {teamId: 'Team membership is required to share a filter'});
  } else if (input.teamId) throw new AppError('VALIDATION', 'A personal filter cannot have a team', 422, {teamId: 'Clear the team or choose team visibility'});
}

function uniqueName(ctx, userId, input, exceptId = '') {
  const duplicate = ctx.db.prepare(`SELECT id FROM saved_filters WHERE owner_id=? AND org_id=?
    AND name=? COLLATE NOCASE AND visibility=? AND COALESCE(team_id,'')=COALESCE(?,'') AND id<>?`)
    .get(userId, input.orgId, input.name, input.visibility, input.teamId, exceptId);
  if (duplicate) throw new AppError('CONFLICT', 'You already saved a filter with this name in this destination', 409, {name: 'Choose a distinct name'});
}

function emitFilter(ctx, req, action, before, after) {
  const filter = after ?? before;
  ctx.bus.emit({actorId: req.user.id, orgId: filter.orgId, entityType: 'savedFilter', entityId: filter.id,
    action, before, after, time: ctx.now()});
}

export function createFilter(ctx, req, body) {
  const input = savedFilterInput(body);
  checkFilter(ctx, req, input);
  const id = ctx.id(), now = ctx.now();
  ctx.transaction(() => {
    uniqueName(ctx, req.user.id, input);
    ctx.db.prepare(`INSERT INTO saved_filters(id,org_id,owner_id,team_id,visibility,name,description,query,created_at,updated_at)
      VALUES(?,?,?,?,?,?,?,?,?,?)`).run(id, input.orgId, req.user.id, input.teamId, input.visibility, input.name, input.description, input.query, now, now);
  });
  const filter = publicFilter(ctx.db.prepare('SELECT * FROM saved_filters WHERE id=?').get(id), req.user.id);
  emitFilter(ctx, req, 'created', null, filter);
  return filter;
}

export function updateFilter(ctx, req, id, body) {
  const before = getFilter(ctx, req, id, {edit: true});
  const {expectedRevision, ...changes} = body ?? {};
  const input = {...before, ...savedFilterInput(changes, {partial: true})};
  if (input.orgId !== before.orgId) throw new AppError('VALIDATION', 'A saved filter cannot move organizations', 422, {orgId: 'Create a new filter in the other organization'});
  if (expectedRevision !== undefined && integer(expectedRevision, 'expectedRevision', {min: 1}) !== before.revision) throw new AppError('CONFLICT', 'This filter changed; reload before saving', 409, {expectedRevision: 'The saved revision is newer'});
  checkFilter(ctx, req, input);
  ctx.transaction(() => {
    uniqueName(ctx, req.user.id, input, id);
    ctx.db.prepare('UPDATE saved_filters SET name=?,description=?,query=?,visibility=?,team_id=?,revision=revision+1,updated_at=? WHERE id=?')
      .run(input.name, input.description, input.query, input.visibility, input.teamId, ctx.now(), id);
  });
  const filter = publicFilter(ctx.db.prepare('SELECT * FROM saved_filters WHERE id=?').get(id), req.user.id);
  emitFilter(ctx, req, 'updated', before, filter);
  return filter;
}

export function deleteFilter(ctx, req, id) {
  const before = getFilter(ctx, req, id, {edit: true});
  ctx.db.prepare('DELETE FROM saved_filters WHERE id=?').run(id);
  emitFilter(ctx, req, 'deleted', before, null);
}

import {searchTokens} from './evaluate.js';
import {parseQuery} from './parser.js';
import {quoteQueryValue} from './suggestions.js';
import {validatedQuery} from '../schemas/query.js';

export const QUERY_FIELD_DEFINITIONS = Object.freeze([
  {field: 'text', label: 'Free text', operators: ['prefix', 'phrase'], placeholder: 'Search words or an exact phrase'},
  {field: 'status', label: 'Status', operators: [':', '!='], catalog: 'statuses', placeholder: 'Status name, category or ID'},
  {field: 'assignee', label: 'Assignee', operators: [':', '!='], catalog: 'assignees', placeholder: '@me, unassigned or person'},
  {field: 'label', label: 'Label', operators: [':', '!='], catalog: 'labels', placeholder: 'Label name or ID'},
  {field: 'project', label: 'Project', operators: [':', '!='], catalog: 'projects', placeholder: 'Project key or ID'},
  {field: 'priority', label: 'Priority', operators: [':', '!=', '>', '>=', '<', '<='], placeholder: '0 to 4'},
  {field: 'created', label: 'Created', operators: [':', '!=', '>', '>=', '<', '<='], placeholder: 'YYYY-MM-DD or UTC ISO timestamp'},
  {field: 'updated', label: 'Updated', operators: [':', '!=', '>', '>=', '<', '<='], placeholder: 'YYYY-MM-DD or UTC ISO timestamp'}
]);

const nodeId = () => globalThis.crypto.randomUUID();
export function newQueryCondition(field = 'status') {
  const definition = QUERY_FIELD_DEFINITIONS.find(item => item.field === field);
  if (!definition) throw new Error('Unknown builder field');
  return {id: nodeId(), type: 'condition', field, operator: definition.operators[0], value: '', negated: false};
}
export function newQueryGroup(mode = 'and') {
  return {id: nodeId(), type: 'group', mode, negated: false, children: []};
}

export function builderToQuery(root) {
  function serialize(node, isRoot = false) {
    let source;
    if (node.type === 'group') {
      if (!['and', 'or'].includes(node.mode)) throw new Error('Choose AND or OR for every group');
      if (!node.children.length) {
        if (isRoot && !node.negated) return '';
        throw new Error('Add a condition to every group, or remove the empty group');
      }
      source = '(' + node.children.map(child => serialize(child)).join(node.mode === 'and' ? ' AND ' : ' OR ') + ')';
    } else if (node.type === 'condition') {
      const definition = QUERY_FIELD_DEFINITIONS.find(item => item.field === node.field);
      if (!definition || !definition.operators.includes(node.operator)) throw new Error('Choose a supported operator for ' + node.field);
      const value = String(node.value).trim();
      if (!value) throw new Error('Enter a value for ' + definition.label);
      if (node.field === 'text') {
        if (node.operator === 'phrase') source = JSON.stringify(value);
        else {
          const tokens = searchTokens(value);
          if (!tokens.length) throw new Error('Enter words for prefix search, or choose phrase');
          source = tokens.map(quoteQueryValue).join(' AND ');
          if (tokens.length > 1) source = '(' + source + ')';
        }
      } else source = node.field + node.operator + quoteQueryValue(value);
    } else throw new Error('Unknown query builder node');
    return node.negated ? 'NOT ' + source : source;
  }
  return validatedQuery(serialize(root, true)).query;
}

export function queryToBuilder(source = '') {
  const ast = parseQuery(validatedQuery(source).query);
  function convert(node) {
    if (node.type === 'all') return newQueryGroup();
    if (node.type === 'not') {
      const child = convert(node.child);
      return {...child, negated: !child.negated};
    }
    if (node.type === 'and' || node.type === 'or') {
      const left = convert(node.left), right = convert(node.right);
      const flatten = child => child.type === 'group' && !child.negated && child.mode === node.type ? child.children : [child];
      return {...newQueryGroup(node.type), children: [...flatten(left), ...flatten(right)]};
    }
    if (node.type === 'term') return {...newQueryCondition('text'), operator: node.quoted ? 'phrase' : 'prefix', value: node.value};
    const operator = node.operator === '=' ? ':' : node.operator;
    return {...newQueryCondition(node.field), operator, value: String(node.value)};
  }
  const result = convert(ast);
  return result.type === 'group' ? result : {...newQueryGroup(), children: [result]};
}

export function updateQueryNode(root, id, change) {
  if (root.id === id) return typeof change === 'function' ? change(root) : {...root, ...change};
  if (root.type !== 'group') return root;
  return {...root, children: root.children.map(child => updateQueryNode(child, id, change))};
}

export function removeQueryNode(root, id) {
  if (root.id === id) return newQueryGroup();
  if (root.type !== 'group') return root;
  return {...root, children: root.children.filter(child => child.id !== id).map(child => removeQueryNode(child, id))};
}

export function moveQueryChild(root, groupId, from, to) {
  return updateQueryNode(root, groupId, group => {
    if (group.type !== 'group' || from < 0 || to < 0 || from >= group.children.length || to >= group.children.length) return group;
    const children = [...group.children];
    const [moving] = children.splice(from, 1);
    children.splice(to, 0, moving);
    return {...group, children};
  });
}

export function conditionChoices(field, catalog = {}) {
  if (field === 'priority') return [0, 1, 2, 3, 4].map(value => ({value: String(value), label: String(value)}));
  const definition = QUERY_FIELD_DEFINITIONS.find(item => item.field === field);
  const values = definition?.catalog ? catalog[definition.catalog] ?? [] : [];
  const all = field === 'assignee' ? [{value: '@me', label: 'Assigned to me'}, {value: 'unassigned', label: 'Unassigned'}, ...values] : values;
  return [...new Map(all.map(item => [String(item.value), item])).values()];
}

import {fields, text, choice} from '../validate.js';
import {parseQuery} from '../query/parser.js';
import {QuerySyntaxError} from '../query/lexer.js';
import {validation} from '../errors.js';

export function validatedQuery(value = '') {
  const query = text(value, 'query', {min: 0, max: 4000});
  try {
    return {query, ast: parseQuery(query)};
  } catch (error) {
    if (error instanceof QuerySyntaxError) throw validation(error.details, error.message);
    throw error;
  }
}

export function savedFilterInput(body, {partial = false} = {}) {
  fields(body, ['orgId', 'name', 'query', 'visibility', 'teamId', 'description']);
  if (partial && !Object.keys(body).length) throw validation({body: 'Supply at least one filter field'});
  const result = {};
  if (!partial || Object.hasOwn(body, 'orgId')) result.orgId = text(body.orgId, 'orgId', {max: 100});
  if (!partial || Object.hasOwn(body, 'name')) result.name = text(body.name, 'name', {max: 100});
  if (!partial || Object.hasOwn(body, 'query')) result.query = validatedQuery(body.query ?? '').query;
  if (!partial || Object.hasOwn(body, 'visibility')) result.visibility = choice(body.visibility, 'visibility', ['personal', 'team'], 'personal');
  if (!partial || Object.hasOwn(body, 'teamId')) result.teamId = text(body.teamId, 'teamId', {optional: true, max: 100});
  if (!partial || Object.hasOwn(body, 'description')) result.description = text(body.description ?? '', 'description', {min: 0, max: 1000});
  return result;
}

import {useState} from 'preact/hooks';
import {Field, Button, Notice} from '../../components/ui.jsx';
import {filterDraft, filterPayload} from './search-state.js';
import {savedFilterInput} from '../../../../shared/src/index.js';

export function FilterForm({api, filter, orgId, teams = [], onSaved, onCancel, onUnavailable}) {
  const [draft, setDraft] = useState(() => filterDraft(filter, orgId));
  const [busy, setBusy] = useState(false);
  const [revision, setRevision] = useState(filter?.revision);
  const [touched, setTouched] = useState(false);
  const [latest, setLatest] = useState(null);
  const [unavailable, setUnavailable] = useState(false);
  const [error, setError] = useState(null);
  const update = (field, value) => {setDraft(previous => ({...previous, [field]: value})); setTouched(true);};
  const details = error?.details ?? {};
  async function save(event) {
    event.preventDefault();
    setError(null);
    setBusy(true);
    try {
      const payload = filterPayload(draft, revision);
      const {expectedRevision, ...validated} = payload;
      savedFilterInput(validated);
      if (draft.visibility === 'team' && !draft.teamId) throw new Error('Choose a team to share this filter');
      const result = filter?.id ? await api.patch('/filters/' + filter.id, payload) : await api.post('/filters', payload);
      setTouched(false);
      onSaved(result.filter);
    } catch (failure) {
      setError(failure);
      if ([403, 404].includes(failure.status)) {setUnavailable(true); onUnavailable?.();}
    }
    finally {setBusy(false);}
  }
  async function inspectLatest() {
    setBusy(true);
    try {
      const result = await api.get('/filters/' + filter.id);
      setLatest(result.filter);
      setError(null);
    } catch (failure) {
      setError(failure);
      if ([403, 404].includes(failure.status)) {setUnavailable(true); onUnavailable?.();}
    } finally {setBusy(false);}
  }
  function loadLatest() {
    if (touched && !globalThis.confirm('Replace your unsaved draft with the latest saved filter?')) return;
    setDraft(filterDraft(latest));
    setRevision(latest.revision);
    setTouched(false);
    setLatest(null);
    setError(null);
  }
  function cancel() {
    if (!touched || globalThis.confirm('Discard your unsaved filter edits?')) onCancel();
  }
  return <form className="filter-form" onSubmit={save}>
    <h2>{filter?.id ? 'Edit saved filter' : 'Save this search'}</h2>
    <Notice error={error}/>
    {unavailable && <Notice>This filter is no longer editable with your current access. Your draft remains here so you can read it before closing.</Notice>}
    {error?.status === 409 && filter?.id && <Button type="button" busy={busy} onClick={inspectLatest}>Inspect latest saved version</Button>}
    {latest && <aside aria-label="Latest saved filter">
      <h3>Latest saved version · revision {latest.revision}</h3>
      <p>{latest.name}</p><pre>{latest.query || 'All accessible issues'}</pre><p>{latest.description}</p>
      <p>Your local draft has been retained. Load this version only when you want to replace the editor contents.</p>
      <Button type="button" onClick={loadLatest}>Load latest saved version</Button>
    </aside>}
    {revision != null && <p>Editing revision {revision}{touched ? ' · unsaved changes' : ''}</p>}
    <Field label="Name" error={details.name} value={draft.name} required maxLength={100} onInput={event => update('name', event.currentTarget.value)}/>
    <Field label="Description" error={details.description}>
      <textarea value={draft.description} maxLength={1000} onInput={event => update('description', event.currentTarget.value)}/>
    </Field>
    <Field label="Query" error={details.query}>
      <textarea value={draft.query} maxLength={4000} onInput={event => update('query', event.currentTarget.value)} aria-label="Saved filter query"/>
    </Field>
    <Field label="Visibility" error={details.visibility}>
      <select value={draft.visibility} onChange={event => update('visibility', event.currentTarget.value)}>
        <option value="personal">Personal · only you</option>
        <option value="team">Shared with a team</option>
      </select>
    </Field>
    {draft.visibility === 'team' && <Field label="Team" error={details.teamId}>
      <select required value={draft.teamId} onChange={event => update('teamId', event.currentTarget.value)}>
        <option value="">Choose one of your teams</option>
        {teams.map(team => <option key={team.id} value={team.id}>{team.name}</option>)}
      </select>
      {!teams.length && <p>Join a team in this organization before sharing a filter.</p>}
    </Field>}
    <p>Every run uses the current viewer’s project access. Only the creator can edit or delete a filter.</p>
    <div className="actions"><Button busy={busy} disabled={unavailable} type="submit">Save filter</Button><Button type="button" disabled={busy} onClick={cancel}>Cancel</Button></div>
  </form>;
}

import {useEffect, useState} from 'preact/hooks';
import {Page, Field, Button, Notice, Empty, Loading, useLoad, ConfirmButton} from '../../components/ui.jsx';
import {routeLink} from '../../router.js';
import {FilterForm} from './filter-form.jsx';
import {searchLocation} from './search-state.js';

export function FiltersPage({api, query, navigate}) {
  const organizations = useLoad(() => api.get('/orgs'), []);
  const [orgId, setOrgId] = useState(query.orgId ?? '');
  const [visibility, setVisibility] = useState('all');
  const [nameQuery, setNameQuery] = useState('');
  const [owned, setOwned] = useState(false);
  const [teamId, setTeamId] = useState('');
  const [cursors, setCursors] = useState(['']);
  const [editing, setEditing] = useState(null);
  const [error, setError] = useState(null);
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);
  const options = useLoad(() => orgId ? api.get('/filters/options?orgId=' + encodeURIComponent(orgId)) : {teams: []}, [orgId]);
  const listing = useLoad(() => {
    if (!orgId) return {items: [], total: 0};
    return api.get('/filters?' + new URLSearchParams({orgId, visibility, q: nameQuery, owned: String(owned), teamId, limit: '25', cursor: cursors.at(-1)}));
  }, [orgId, visibility, nameQuery, owned, teamId, cursors.at(-1)]);
  useEffect(() => {if (!orgId && organizations.data?.items.length) setOrgId(organizations.data.items[0].id);}, [organizations.data]);
  function changeOrg(value) {
    setOrgId(value);
    setTeamId('');
    setCursors(['']);
    setEditing(null);
    setMessage('');
  }
  async function remove(filter) {
    setError(null);
    setBusy(true);
    try {
      await api.delete('/filters/' + filter.id);
      setMessage('Deleted “' + filter.name + '”.');
      setCursors(['']);
      listing.reload();
    } catch (failure) {setError(failure); if ([403, 404].includes(failure.status)) listing.reload();}
    finally {setBusy(false);}
  }
  async function edit(filter) {
    setError(null);
    try {setEditing((await api.get('/filters/' + filter.id)).filter);}
    catch (failure) {setError(failure); if ([403, 404].includes(failure.status)) listing.reload();}
  }
  return <Page title="Saved filters" actions={<a href={routeLink('/search', {orgId})}>Search issues</a>}>
    <Notice error={error ?? organizations.error ?? listing.error ?? options.error}/><Notice>{message}</Notice>
    {organizations.loading ? <Loading/> : !organizations.data?.items.length ? <Empty>Join an organization before saving a filter.</Empty> : <>
      <div className="search-controls">
        <Field label="Organization"><select value={orgId} onChange={event => changeOrg(event.currentTarget.value)}>
          <option value="">Choose an organization</option>{organizations.data.items.map(org => <option key={org.id} value={org.id}>{org.name}</option>)}
        </select></Field>
        <Field label="Find a saved filter"><input value={nameQuery} placeholder="Name or description" onInput={event => {setNameQuery(event.currentTarget.value); setCursors(['']);}}/></Field>
        <Field label="Visibility"><select value={visibility} onChange={event => {setVisibility(event.currentTarget.value); setCursors(['']);}}>
          <option value="all">Personal and shared</option><option value="personal">Personal</option><option value="team">Team shared</option>
        </select></Field>
        <Field label="Team"><select value={teamId} onChange={event => {setTeamId(event.currentTarget.value); setCursors(['']);}}>
          <option value="">All my teams</option>{options.data?.teams.map(team => <option key={team.id} value={team.id}>{team.name}</option>)}
        </select></Field>
        <label><input type="checkbox" checked={owned} onChange={event => {setOwned(event.currentTarget.checked); setCursors(['']);}}/>Created by me</label>
      </div>
      <Button disabled={!orgId || busy || listing.loading} onClick={listing.reload}>Refresh filters</Button>
      <Button disabled={!orgId || busy} onClick={() => setEditing({})}>Create saved filter</Button>
      {editing && <FilterForm key={editing.id ?? 'new'} api={api} orgId={orgId} filter={editing} teams={options.data?.teams}
        onCancel={() => setEditing(null)} onUnavailable={listing.reload} onSaved={filter => {setEditing(null); setMessage('Saved “' + filter.name + '”.'); setCursors(['']); listing.reload();}}/>}
      {listing.loading ? <Loading/> : !listing.data?.items.length ? <Empty>No saved filters in this view. Create one or ask a teammate to share one.</Empty> : <>
        <p>{listing.data.total} accessible filters</p>
        <ul className="saved-filters">{listing.data.items.map(filter => <li key={filter.id}>
          <article><h2><a href={'#' + searchLocation(filter.orgId, filter.query)}>{filter.name}</a></h2>
            {filter.description && <p>{filter.description}</p>}
            <p>Updated {new Date(filter.updatedAt).toLocaleString()}</p>
            <pre>{filter.query || 'All accessible issues'}</pre>
            <p>{filter.visibility === 'personal' ? 'Personal' : 'Team: ' + (options.data?.teams.find(team => team.id === filter.teamId)?.name ?? 'Shared team')} · revision {filter.revision}</p>
            <div className="actions"><Button onClick={() => navigate(searchLocation(filter.orgId, filter.query))}>Run filter</Button>
              {filter.canEdit && <><Button disabled={busy} onClick={() => edit(filter)}>Edit</Button>
                <ConfirmButton disabled={busy} message={'Delete saved filter “' + filter.name + '”?'} onConfirm={() => remove(filter)}>Delete</ConfirmButton></>}
            </div>
          </article>
        </li>)}</ul>
        <div className="actions"><Button disabled={busy || cursors.length < 2} onClick={() => setCursors(previous => previous.slice(0, -1))}>Previous</Button>
          <span>Page {cursors.length}</span><Button disabled={busy || !listing.data.nextCursor} onClick={() => setCursors(previous => [...previous, listing.data.nextCursor])}>Next</Button></div>
      </>}
    </>}
  </Page>;
}
